# Meeting 3: self-practice at home, after s-home, by topic. The order of the slides is set by HOME_T in content_l3.py.
# Every topic: "find the mistake" first, then a ladder from easy to hard. One technique per exercise, as in class.
# Every solution line says what we do and why; lines are checked at build time (CHK: at the values where the line holds).

_homeroute3 = [('1', 'אחוזים', 'מצאו את הטעות, ושמונה תרגילים', 'hx-p'), ('2', 'פונקציות', 'מצאו את הטעות, הצבה ותחום', 'hx-f'),
               ('3', 'משוואת הישר', 'מצאו את הטעות, וישר משתי נקודות', 'hx-l'), ('4', 'מקבילים ומאונכים', 'ארבעה תרגילים', 'h-pp'),
               ('5', 'נקודות חיתוך', 'מצאו את הטעות, ובעיה מילולית', 'hx-i')]
S('s-home', 'תרגול עצמי לבית', 'תרגול עצמי לבית: בחרו נושא',
  '<div class="route r5">' + ''.join(f'<button class="rcard" data-go="{g}"><div class="n">{k}</div><b>{t}</b><span>{TX(d)}</span></button>' for k, t, d, g in _homeroute3) + '</div>'
  + BAND('note', 'בכל נושא: קודם ״מצאו את הטעות״, ואחר כך תרגילים מהקל אל הקשה, בדרך שלמדנו בכיתה. פותרים על דף, שורה לכל פעולה, ורק אז מקלידים ובודקים. ״פתרון בשלבים״ מציג שלב אחד בכל לחיצה, עם הסבר.'),
  kick=KICK('תרגול עצמי'))

_FIND = ' בפתרון יש טעות אחת. לחצו על השורה הראשונה שבה נפלה הטעות.'

# ================================================================ topic 1: percentages
ERR('hx-p', 'מצאו את הטעות', 'מצאו את הטעות: שני שינויים ברצף',
    '**מחיר של מוצר הוא 400 ש״ח. המחיר עלה ב-20%, ואחר כך עלה עוד ב-10%. דני חישב את המחיר הסופי, וקיבל 520 ש״ח.**' + _FIND,
    [('~1.2', 'עלייה של 20% היא כפל ב-$1 + 20/100 = 1.2$.', 'המקדם של העלייה הראשונה:'),
     ('400*1.2 = 480', 'המחיר אחרי העלייה הראשונה נכון.', 'אחרי העלייה הראשונה:'),
     ('=480+0.1*400', '', 'אחרי העלייה השנייה:'),
     ('=520', '', 'המחיר הסופי:')], 2,
    'העלייה השנייה היא 10% מהמחיר שהיה ממש לפניה, כלומר מ-480, ולא מ-400. כל אחוז נלקח מהמחיר האחרון.',
    [('=480+0.1*480', '10% מ-480 הם 48.'),
     ('=480*1.1', 'או בכפל אחד, במקדם 1.1.'),
     ('=528', 'המחיר הסופי: 528 ש״ח.')],
    ans='528', wrong='520', show='')

