# ================================================================ topic 3: the equation of a line
ERR('hx-l', 'מצאו את הטעות', 'מצאו את הטעות: משוואת ישר משתי נקודות',
    '**שירה מצאה את משוואת הישר שעובר דרך $(2, 7)$ ו-$(4, 11)$, וקיבלה $y = 0.5x + 6$.**' + _FIND,
    [('~(2, 7)_,_(4, 11)', 'הנקודות נכונות.', 'הנקודות:'),
     ('m = {f|4-2|11-7} = {f|2|4} = 0.5', '', 'השיפוע:'),
     ('7 = 0.5·2+b', '', 'מציבים את $(2, 7)$:'),
     ('b = 6', '', ''),
     ('y = 0.5x+6', '', 'המשוואה:')], 1,
    'השיפוע הפוך: שירה חילקה את ההפרש ב-$x$ בהפרש ב-$y$. השיפוע הוא ההפרש ב-$y$ חלקי ההפרש ב-$x$: $(11 - 7)/(4 - 2) = 2$.',
    [(CHK('m = {f|11-7|4-2} = {f|4|2} = 2', m=2), 'ההפרש ב-$y$ חלקי ההפרש ב-$x$.'),
     (CHK('7 = 2·2+b', b=3), 'מציבים $m = 2$ ואת $(2, 7)$.'),
     (CHK('7-4 = b', b=3), 'מעבירים את 4 לאגף השמאלי.'),
     (CHK('y = 2x+3', dict(x=2, y=7), dict(x=4, y=11)), 'המשוואה. בדיקה: $2·4 + 3 = 11$.')],
    expr='y=2x+3', ans={'x': '2', 'y': '7', 'm': '2', 'b': '3'}, wrong={'x': '2', 'y': '7', 'm': '0.5', 'b': '6'}, show='')

