S('hw-i', 'בעיה מילולית: חדר כושר', 'בעיה מילולית: איזה מכון כושר זול יותר?',
  '<div class="row eq2"><div class="col">'
  + CARD(P('**במכון כושר A משלמים 100 ש״ח מנוי לחודש, ועוד 20 ש״ח לכל כניסה. במכון B אין מנוי, ומשלמים 40 ש״ח לכל כניסה.**') + P('**בכמה כניסות בחודש שני המכונים עולים אותו דבר? ומתי כדאי A?**'), cls='qstem')
  + ST(1, '<b class="ct">שלב 1: מסמנים</b>' + P('$x$ מספר הכניסות בחודש, $y$ התשלום בש״ח.'), cls='card')
  + ST(2, '<b class="ct">שלב 2: שני ישרים</b>' + SYS('y=20x+100', 'y=40x') + P('A: 20 לכל כניסה ועוד 100 קבועים. B: 40 לכל כניסה.'), cls='card')
  + '</div><div>'
  + TRYXY('t-hw1', 'שלב 3: מצאו את נקודת החיתוך.', {'x': '5', 'y': '200'}, ['מציבים: $40x = 20x + 100$.', 'מעבירים את $20x$ שמאלה: $20x = 100$.'],
          [('{h|40x} = 20x+100', 'בנקודת החיתוך התשלום זהה. מציבים את $y$ של B במשוואה של A.'), ('40x-20x = 100', 'מעבירים את $20x$ שמאלה. המקדם של $x$ חיובי.'),
           ('20x = 100 @:20', 'מכנסים.'), ('x = 5', 'מחלקים ב-20.'), ('y = 40·5 = 200', 'חוזרים לביטוי של B.'), ('20·5+100 = 200', 'שלב 4, בודקים ב-A: גם 200.'),
           ('~', 'שלב 5, במילים: ב-5 כניסות שני המכונים עולים 200 ש״ח. ביותר מ-5 כניסות A זול יותר, ובפחות מ-5 B זול יותר.')],
          w='$(5, 200)$.', expr='y=20x+100;y=40x', show=False)
  + '</div></div>', kick=KICK('תרגול עצמי'))
